L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "\227\129\147\227\130\140\227\129\175\227\129\147\227\130\140\227\129\175\227\128\130\229\176\138\227\129\141\230\150\185\227\129\140\227\129\147\227\129\174\232\128\129\228\186\186\227\129\174\227\129\159\227\130\129\227\129\171\231\155\180\230\142\165\232\166\139\233\128\129\227\130\138\227\129\171\230\157\165\227\129\166\227\129\143\227\129\160\227\129\149\227\130\139\227\129\168\227\129\175\227\128\130"
L10_1.m_Talk_ENG = "Well, well, well... If it isn\226\128\153t the great Lady Nanahara herself. Here to bid me farewell?"
L10_1.m_Talk_TWN = "\233\128\153\230\152\175\232\170\176\229\149\138\239\188\159\230\178\146\230\131\179\229\136\176\230\156\131\230\156\137\229\166\130\230\173\164\229\176\138\232\178\180\231\154\132\228\186\186\228\190\134\233\128\129\230\136\145\233\128\153\232\128\129\233\160\173\228\184\128\231\168\139\229\145\162\227\128\130"
L10_1.m_Talk_THA = "\224\185\129\224\184\171\224\184\161 \224\185\129\224\184\171\224\184\161 \224\185\129\224\184\171\224\184\161... \224\184\153\224\184\181\224\185\136\224\184\161\224\184\177\224\184\153\224\184\151\224\185\136\224\184\178\224\184\153\224\184\171\224\184\141\224\184\180\224\184\135\224\184\153\224\184\178\224\184\153\224\184\176\224\184\174\224\184\178\224\184\163\224\184\176\224\184\156\224\184\185\224\185\137\224\184\162\224\184\180\224\185\136\224\184\135\224\185\131\224\184\171\224\184\141\224\185\136\224\184\161\224\184\180\224\185\131\224\184\138\224\185\136\224\184\171\224\184\163\224\184\183\224\184\173 \224\184\161\224\184\178\224\184\129\224\184\165\224\185\136\224\184\178\224\184\167\224\184\132\224\184\179\224\184\173\224\184\179\224\184\165\224\184\178\224\184\130\224\185\137\224\184\178\224\184\171\224\184\163\224\184\183\224\184\173\224\184\173\224\184\162\224\185\136\224\184\178\224\184\135\224\185\132\224\184\163\224\184\129\224\184\177\224\184\153?"
L10_1.m_Talk_VTN = "Ch\195\160, ch\195\160, ch\195\160... Ch\225\186\179ng ph\225\186\163i Ti\225\187\131u th\198\176 Nanahara v\196\169 \196\145\225\186\161i \196\145\195\162y sao. T\225\187\155i \196\145\195\162y \196\145\225\187\131 ch\195\160o t\225\186\161m bi\225\187\135t \195\160?"
L10_1.m_Talk_SCN = "\231\156\159\230\152\175\230\132\143\229\164\150\229\149\138\239\188\159\230\178\161\230\131\179\229\136\176\230\130\168\232\191\153\228\185\136\233\171\152\232\180\181\231\154\132\228\186\186\239\188\140\229\177\133\231\132\182\228\188\154\228\186\178\232\135\170\230\157\165\233\128\129\232\128\129\230\156\189\227\128\130"
